"""Program to stream pre-recorded neural data to LSL."""
import sys
import getopt
import time
from pylsl import StreamInfo, StreamOutlet, local_clock

def main(argv):
    srate = 100  # 100Hz for now, TODO: support30kHz sampling rate
    name = 'NeuralData'
    type = 'EEG'
    n_channels = 16
    data_length = 1500  # Length of your neural_data array
    
    try:
        opts, args = getopt.getopt(argv, "hs:c:n:t:", longopts=["srate=", "channels=", "name=", "type"])
    except getopt.GetoptError:
        print('SendNeuralData.py -s <sampling_rate> -n <stream_name> -t <stream_type>')
        sys.exit(2)
    for opt, arg in opts:
        if opt == '-h':
            print('SendNeuralData.py -s <sampling_rate> -n <stream_name> -t <stream_type>')
            sys.exit()
        elif opt in ("-s", "--srate"):
            srate = float(arg)
        elif opt in ("-c", "--channels"):
            n_channels = int(arg)
        elif opt in ("-n", "--name"):
            name = arg
        elif opt in ("-t", "--type"):
            type = arg

    info = StreamInfo(name, type, n_channels, srate, 'float32', 'myuid34234')
    outlet = StreamOutlet(info)

    print("now sending data...")
    start_time = local_clock()
    sent_samples = 0
    
    # Calculate how many full cycles through the data we need per second
    cycles_per_second = srate / data_length
    
    while True:
        elapsed_time = local_clock() - start_time
        required_samples = int(srate * elapsed_time) - sent_samples
        
        for sample_ix in range(required_samples):
            # Calculate position in neural_data, accounting for multiple cycles
            current_pos = (sent_samples + sample_ix) % data_length
            
            mysample = [
                neural_data[(current_pos + i) % data_length] 
                for i in range(n_channels)
            ]
            outlet.push_sample(mysample)
            
        sent_samples += required_samples
        
        # More precise timing control
        # Sleep for a shorter duration to maintain high sampling rate
        time.sleep(0.1)  # 1ms sleep instead of 10ms

if __name__ == '__main__':
    main(sys.argv[1:])